// Interface naming: IPrefix
public interface IDamageable
{
    void TakeDamage(float amount);
    bool IsAlive { get; }
}

// MonoBehaviour naming: Noun + Verb/Role
public class EnemyHealth : MonoBehaviour, IDamageable
{
    [Header("Health Settings")]
    [SerializeField] private float maxHealth = 100f;
    [Tooltip("Damage reduction multiplier from armor")]
    [Range(0f, 1f)]
    [SerializeField] private float armorMultiplier = 0.2f;

    // Private fields: camelCase with _prefix
    private float _currentHealth;
    private bool _isInvulnerable;

    // Public properties: PascalCase
    public bool IsAlive => _currentHealth > 0f;
    public float HealthPercent => _currentHealth / maxHealth;

    private void Awake()
    {
        _currentHealth = maxHealth;
    }

    public void TakeDamage(float amount)
    {
        if (_isInvulnerable || !IsAlive) return;

        float finalDamage = amount * (1f - armorMultiplier);
        _currentHealth = Mathf.Max(0f, _currentHealth - finalDamage);

        if (!IsAlive)
        {
            OnDeath();
        }
    }

    private void OnDeath()
    {
        // Event-driven: notify systems without direct coupling
        EventManager.Instance.Raise(new EnemyDeathEvent { Enemy = this });

        // Return to pool instead of Destroy
        ObjectPoolManager.Instance.ReturnEnemy(gameObject);
    }
}

using UnityEngine;

public class WeaponStats : MonoBehaviour
{
    [Header("Weapon Configuration")]
    [SerializeField] private float baseDamage = 25f;
    [SerializeField] private float fireRate = 0.15f;
    [SerializeField] private int maxAmmo = 30;

    // Public read-only properties: external code can observe but not modify
    public float Damage => baseDamage;
    public float FireRate => fireRate;
    public int CurrentAmmo { get; private set; }
    public bool CanFire => CurrentAmmo > 0 && _fireCooldown <= 0f;

    // Private state
    private float _fireCooldown;
    private bool _isReloading;

    private void Awake()
    {
        CurrentAmmo = maxAmmo;
    }

    private void Update()
    {
        // Decrement cooldown safely
        if (_fireCooldown > 0f)
        {
            _fireCooldown -= Time.deltaTime;
        }
    }

    public bool TryFire()
    {
        if (!CanFire) return false;

        CurrentAmmo--;
        _fireCooldown = fireRate;

        // Event-driven: notify without direct coupling
        EventManager.Instance.Raise(new WeaponFiredEvent 
        { 
            Weapon = this, 
            RemainingAmmo = CurrentAmmo 
        });

        return true;
    }

    public void Reload()
    {
        if (_isReloading || CurrentAmmo == maxAmmo) return;

        _isReloading = true;
        // In a real game, use a coroutine or async for reload timing
        CurrentAmmo = maxAmmo;
        _isReloading = false;
    }
}

using UnityEngine;

public class SafeReferences : MonoBehaviour
{
    [SerializeField] private Transform target;
    [SerializeField] private AudioSource sfxSource;

    private void Awake()
    {
        // Defensive: fail fast with clear messages
        Debug.Assert(target != null, "[SafeReferences] Target Transform is not assigned!", this);
        Debug.Assert(sfxSource != null, "[SafeReferences] AudioSource is not assigned!", this);

        // Disable script if critical references are missing
        if (target == null || sfxSource == null)
        {
            enabled = false;
            return;
        }
    }

    private void Update()
    {
        // NEVER use ?. in Unity — it bypasses the fake null check!
        // BAD: target?.position (can crash if object is destroyed)

        // GOOD: explicit null check
        if (target != null)
        {
            Vector3 direction = (target.position - transform.position).normalized;
            transform.rotation = Quaternion.LookRotation(direction);
        }
    }

    private void PlaySFX(AudioClip clip)
    {
        // Guard clause pattern
        if (clip == null) return;
        if (sfxSource == null) return;
        if (!sfxSource.isActiveAndEnabled) return;

        sfxSource.PlayOneShot(clip);
    }
}

