using UnityEngine;
using UnityEngine.UI;
using System.Text;

public class StringOptimization : MonoBehaviour
{
    [SerializeField] private Text fpsText;
    [SerializeField] private Animator animator;

    // Cache hashes ONCE as static readonly (shared across all instances)
    private static readonly int IsRunningHash = Animator.StringToHash("IsRunning");
    private static readonly int SpeedHash = Animator.StringToHash("Speed");

    // Pre-allocated StringBuilder (zero allocation updates)
    private readonly StringBuilder _fpsBuilder = new StringBuilder(16);
    private float _fpsTimer;
    private int _frameCount;

    private void Update()
    {
        // GOOD: Cached hash, zero string operations
        float speed = Input.GetAxis("Vertical");
        animator.SetBool(IsRunningHash, speed != 0f);
        animator.SetFloat(SpeedHash, Mathf.Abs(speed));

        // Update FPS counter efficiently
        _frameCount++;
        _fpsTimer += Time.deltaTime;

        if (_fpsTimer >= 1f)
        {
            // Clear and reuse StringBuilder (no new string objects)
            _fpsBuilder.Clear();
            _fpsBuilder.Append("FPS: ");
            _fpsBuilder.Append(_frameCount);
            fpsText.text = _fpsBuilder.ToString();

            _frameCount = 0;
            _fpsTimer -= 1f;
        }
    }
}

using UnityEngine;
using UnityEngine.SceneManagement;

public class BootLoader : MonoBehaviour
{
    [Header("Scene Configuration")]
    [SerializeField] private string mainMenuSceneName = "MainMenu";
    [SerializeField] private string gameplaySceneName = "Gameplay";

    [Header("Core Systems Prefabs")]
    [SerializeField] private GameObject audioManagerPrefab;
    [SerializeField] private GameObject inputManagerPrefab;
    [SerializeField] private GameObject poolManagerPrefab;

    private static bool _isBooted = false;

    private void Awake()
    {
        // Prevent duplicate boot on restart
        if (_isBooted)
        {
            Destroy(gameObject);
            return;
        }

        _isBooted = true;
        DontDestroyOnLoad(gameObject);

        InitializeCoreSystems();
        LoadMainMenu();
    }

    private void InitializeCoreSystems()
    {
        // Instantiate core managers (exactly once, in order)
        Instantiate(audioManagerPrefab);
        Instantiate(inputManagerPrefab);
        Instantiate(poolManagerPrefab);

        // Verify all systems initialized
        Debug.Assert(AudioManager.Instance != null, "AudioManager failed to initialize");
        Debug.Assert(InputManager.Instance != null, "InputManager failed to initialize");
        Debug.Assert(ObjectPoolManager.Instance != null, "ObjectPoolManager failed to initialize");

        Debug.Log("[BootLoader] Core systems initialized successfully.");
    }

    private void LoadMainMenu()
    {
        SceneManager.LoadScene(mainMenuSceneName, LoadSceneMode.Additive);
    }

    public static void StartGame()
    {
        // Unload menu, load gameplay additively
        SceneManager.UnloadSceneAsync("MainMenu");
        SceneManager.LoadScene("Gameplay", LoadSceneMode.Additive);
    }

    public static void ReturnToMenu()
    {
        SceneManager.UnloadSceneAsync("Gameplay");
        SceneManager.LoadScene("MainMenu", LoadSceneMode.Additive);
    }
}

using UnityEngine;
using UnityEngine.SceneManagement;
using System.Collections;

public class SceneChunkLoader : MonoBehaviour
{
    [Header("Chunk Settings")]
    [SerializeField] private float loadDistance = 50f;
    [SerializeField] private float unloadDistance = 80f;
    [SerializeField] private Transform playerTransform;

    [System.Serializable]
    public class SceneChunk
    {
        public string sceneName;
        public Vector3 worldPosition;
        [HideInInspector] public bool isLoaded;
    }

    [SerializeField] private SceneChunk[] chunks;

    private void Update()
    {
        foreach (var chunk in chunks)
        {
            float sqrDist = (chunk.worldPosition - playerTransform.position).sqrMagnitude;

            if (sqrDist < loadDistance * loadDistance && !chunk.isLoaded)
            {
                StartCoroutine(LoadChunkAsync(chunk));
            }
            else if (sqrDist > unloadDistance * unloadDistance && chunk.isLoaded)
            {
                StartCoroutine(UnloadChunkAsync(chunk));
            }
        }
    }

    private IEnumerator LoadChunkAsync(SceneChunk chunk)
    {
        AsyncOperation loadOp = SceneManager.LoadSceneAsync(chunk.sceneName, LoadSceneMode.Additive);
        loadOp.allowSceneActivation = true;

        while (!loadOp.isDone)
        {
            // Progress: 0 to 0.9 (0.9 = loaded, waiting for activation)
            float progress = Mathf.Clamp01(loadOp.progress / 0.9f);
            Debug.Log($"[SceneChunkLoader] Loading {chunk.sceneName}: {progress:P0}");
            yield return null;
        }

        chunk.isLoaded = true;
        Debug.Log($"[SceneChunkLoader] {chunk.sceneName} loaded successfully.");
    }

    private IEnumerator UnloadChunkAsync(SceneChunk chunk)
    {
        AsyncOperation unloadOp = SceneManager.UnloadSceneAsync(chunk.sceneName);
        yield return unloadOp;

        chunk.isLoaded = false;

        // Force garbage collection of unused assets (careful: causes a small hitch)
        // Use only during loading screens, not gameplay
        // Resources.UnloadUnusedAssets();

        Debug.Log($"[SceneChunkLoader] {chunk.sceneName} unloaded.");
    }
}

