// Class: PascalCase, descriptive noun + role
public class EnemyPatrolBehavior : MonoBehaviour
{
    // Serialized fields: camelCase with _prefix, descriptive names
    [Header("Patrol Configuration")]
    [Tooltip("Time in seconds to wait at each patrol point")]
    [SerializeField] private float _waitTimeAtWaypoint = 2f;

    [Tooltip("Movement speed in world units per second")]
    [SerializeField] private float _patrolSpeed = 3.5f;

    [Tooltip("Array of world positions to patrol between")]
    [SerializeField] private Vector3[] _patrolWaypoints;

    // Private state: camelCase with _prefix
    private int _currentWaypointIndex;
    private float _waitTimer;
    private bool _isWaiting;
    private Transform _cachedTransform;

    // Public properties: PascalCase, self-documenting
    public bool IsPatrolling => _patrolWaypoints != null && _patrolWaypoints.Length > 1;
    public Vector3 CurrentTarget => _patrolWaypoints[_currentWaypointIndex];

    // Unity lifecycle: PascalCase, standard names
    private void Awake()
    {
        _cachedTransform = transform;
        ValidateWaypoints();
    }

    // Private methods: PascalCase, verb + noun
    private void ValidateWaypoints()
    {
        if (_patrolWaypoints == null || _patrolWaypoints.Length < 2)
        {
            Debug.LogWarning("[EnemyPatrolBehavior] Less than 2 waypoints assigned. Disabling patrol.", this);
            enabled = false;
        }
    }

    private void Update()
    {
        if (!IsPatrolling) return;

        if (_isWaiting)
        {
            UpdateWaitTimer();
        }
        else
        {
            MoveTowardsWaypoint();
        }
    }

    private void UpdateWaitTimer()
    {
        _waitTimer += Time.deltaTime;
        if (_waitTimer >= _waitTimeAtWaypoint)
        {
            _isWaiting = false;
            _waitTimer = 0f;
            AdvanceToNextWaypoint();
        }
    }

    private void MoveTowardsWaypoint()
    {
        Vector3 direction = (CurrentTarget - _cachedTransform.position).normalized;
        _cachedTransform.position += direction * _patrolSpeed * Time.deltaTime;

        if (Vector3.Distance(_cachedTransform.position, CurrentTarget) < 0.1f)
        {
            _isWaiting = true;
        }
    }

    private void AdvanceToNextWaypoint()
    {
        _currentWaypointIndex = (_currentWaypointIndex + 1) % _patrolWaypoints.Length;
    }

    // Event handler: On + EventName
    private void OnPlayerDetected(Vector3 playerPosition)
    {
        // Switch from patrol to chase behavior
        enabled = false;
        // Notify chase system...
    }
}

