using UnityEngine;
using System.Text;
using System.Collections.Generic;

public class ZeroAllocationUpdate : MonoBehaviour
{
    [Header("UI References")]
    [SerializeField] private UnityEngine.UI.Text _fpsText;
    [SerializeField] private UnityEngine.UI.Text _scoreText;

    // Pre-allocated reusable objects
    private readonly StringBuilder _stringBuilder = new StringBuilder(32);
    private readonly List<Collider> _overlapBuffer = new List<Collider>(20);

    // Cached state
    private float _fpsTimer;
    private int _frameCount;
    private int _currentScore;
    private static readonly int ScoreHash = Animator.StringToHash("Score");

    private void Update()
    {
        // ZERO ALLOCATION PATTERNS:

        // 1. Reuse StringBuilder instead of string concatenation
        _frameCount++;
        _fpsTimer += Time.deltaTime;

        if (_fpsTimer >= 1f)
        {
            _stringBuilder.Clear();
            _stringBuilder.Append("FPS: ");
            _stringBuilder.Append(_frameCount);
            _fpsText.text = _stringBuilder.ToString();

            _frameCount = 0;
            _fpsTimer -= 1f; // Avoid precision drift from setting to 0
        }

        // 2. Reuse pre-allocated List with Clear()
        _overlapBuffer.Clear();
        int hitCount = Physics.OverlapSphereNonAlloc(
            transform.position, 5f, _overlapBuffer.ToArray(), 
            LayerMask.GetMask("Enemy")
        );
        // Note: OverlapSphereNonAlloc with array is better — see below

        // 3. No LINQ — manual filtering with guard clauses
        for (int i = 0; i < _overlapBuffer.Count; i++)
        {
            Collider hit = _overlapBuffer[i];
            if (hit == null) continue;
            if (!hit.CompareTag("Enemy")) continue;

            ProcessEnemy(hit);
        }

        // 4. No closure allocations — avoid lambdas in hot paths
        // BAD: enemies.ForEach(e => e.TakeDamage(10)); // Allocates delegate!
        // GOOD: Manual loop (shown above)

        // 5. Cached hashes for animator
        // _animator.SetInteger(ScoreHash, _currentScore);
    }

    private void ProcessEnemy(Collider enemyCollider)
    {
        // Process enemy...
    }

    // EVEN BETTER: Pre-allocated array for NonAlloc physics
    private readonly Collider[] _physicsBuffer = new Collider[10];

    private void UpdatePhysics_NonAlloc()
    {
        // OverlapSphereNonAlloc with array — zero allocation, no List needed
        int hitCount = Physics.OverlapSphereNonAlloc(
            transform.position, 
            5f, 
            _physicsBuffer, 
            LayerMask.GetMask("Enemy")
        );

        for (int i = 0; i < hitCount; i++)
        {
            ProcessEnemy(_physicsBuffer[i]);
        }
    }
}

