    public void CollectGarbageDuringLoading()
    {
        // Force a full collection between levels
        GC.Collect();
        GC.WaitForPendingFinalizers();
        GC.Collect(); // Collect objects finalized in previous step

        // Unload unused assets (causes a hitch, use during loading only)
        Resources.UnloadUnusedAssets();

        Debug.Log("[GCManagement] Garbage collected during loading screen.");
    }

    // For Unity 2022+ incremental GC: just enable it in Player Settings
    // No code needed — the engine handles it automatically

    // Monitor GC pressure in development
    private void Update()
    {
        #if UNITY_EDITOR
        // Log GC collection count (diagnostic only — remove in production)
        if (Time.frameCount % 300 == 0) // Every 5 seconds at 60 FPS
        {
            long memoryUsed = GC.GetTotalMemory(false);
            Debug.Log($"[GCManagement] Heap size: {memoryUsed / 1024f:F1} KB");
        }
        #endif
    }
}

