    {
        for (int i = 0; i < _pelletCount; i++)
        {
            Vector3 spread = Quaternion.Euler(Random.Range(-_spreadAngle, _spreadAngle), Random.Range(-_spreadAngle, _spreadAngle), 0) * direction;
            if (Physics.Raycast(origin.position, spread, out RaycastHit hit, _range, _hitLayers))
                if (hit.collider.TryGetComponent<IDamageable>(out var target))
                    target.TakeDamage(_damagePerPellet);
        }
    }
}

