public class WeaponInstance : MonoBehaviour
{
    [SerializeField] private WeaponData _weaponData;
    [SerializeField] private Transform _firePoint;
    private int _currentAmmo;
    private float _fireCooldown;
    private float _currentRecoil;
    private void Awake()
    {
        if (_weaponData == null) { Debug.LogError("[WeaponInstance] WeaponData not assigned!", this); enabled = false; return; }
        _currentAmmo = _weaponData.MagazineSize;
    }
    private void Update()
    {
        if (_fireCooldown > 0) _fireCooldown -= Time.deltaTime;
        if (Input.GetButton("Fire1") && _fireCooldown <= 0 && _currentAmmo > 0) Fire();
    }
    private void Fire()
    {
        _currentAmmo--;
        _fireCooldown = _weaponData.FireRate;
        Vector3 spread = Quaternion.Euler(Random.Range(-_weaponData.AccuracySpread, _weaponData.AccuracySpread) + _currentRecoil, Random.Range(-_weaponData.RecoilHorizontal, _weaponData.RecoilHorizontal), 0) * _firePoint.forward;
        GameObject projectile = ObjectPoolManager.Instance.GetProjectile(_weaponData.ProjectilePrefab);
        projectile.transform.SetPositionAndRotation(_firePoint.position, Quaternion.LookRotation(spread));
        if (projectile.TryGetComponent<Projectile>(out var proj)) proj.Initialize(_weaponData.BaseDamage, _weaponData.ProjectileSpeed, _weaponData.ProjectileLifetime);
        _currentRecoil += _weaponData.RecoilVertical;
        if (_weaponData.FireSFX != null) AudioManager.Instance.PlaySFX(_weaponData.FireSFX, _firePoint.position);
        if (_weaponData.MuzzleFlashPrefab != null) ObjectPoolManager.Instance.SpawnVFX(_weaponData.MuzzleFlashPrefab, _firePoint.position, _firePoint.rotation);
    }
    public void Reload()
    {
        if (_currentAmmo == _weaponData.MagazineSize) return;
        if (_weaponData.ReloadSFX != null) AudioManager.Instance.PlaySFX(_weaponData.ReloadSFX, transform.position);
        _currentAmmo = _weaponData.MagazineSize;
        _currentRecoil = 0f;
    }
}

