public class EventManager : MonoBehaviour
{
    public static EventManager Instance { get; private set; }
    private readonly Dictionary<Type, Delegate> _eventHandlers = new Dictionary<Type, Delegate>();
    private void Awake()
    {
        if (Instance != null && Instance != this) { Destroy(gameObject); return; }
        Instance = this; DontDestroyOnLoad(gameObject);
    }
    public void Subscribe<T>(Action<T> handler) where T : struct
    {
        Type eventType = typeof(T);
        if (_eventHandlers.TryGetValue(eventType, out Delegate existing))
            _eventHandlers[eventType] = Delegate.Combine(existing, handler);
        else
            _eventHandlers[eventType] = handler;
    }
    public void Unsubscribe<T>(Action<T> handler) where T : struct
    {
        Type eventType = typeof(T);
        if (_eventHandlers.TryGetValue(eventType, out Delegate existing))
        {
            _eventHandlers[eventType] = Delegate.Remove(existing, handler);
            if (_eventHandlers[eventType] == null) _eventHandlers.Remove(eventType);
        }
    }
    public void Raise<T>(T eventData) where T : struct
    {
        Type eventType = typeof(T);
        if (_eventHandlers.TryGetValue(eventType, out Delegate handlers))
            (handlers as Action<T>)?.Invoke(eventData);
    }
}

