public class ServiceLocator : MonoBehaviour
{
    private static ServiceLocator _instance;
    private readonly Dictionary<Type, object> _services = new Dictionary<Type, object>();
    private void Awake()
    {
        if (_instance != null) { Destroy(gameObject); return; }
        _instance = this; DontDestroyOnLoad(gameObject); RegisterCoreServices();
    }
    private void RegisterCoreServices()
    {
        Register(FindObjectOfType<AudioManager>());
        Register(FindObjectOfType<EventManager>());
        Register(FindObjectOfType<ObjectPoolManager>());
        Register(FindObjectOfType<SaveSystem>());
    }
    public static void Register<T>(T service) where T : class
    {
        if (_instance == null) { Debug.LogError("ServiceLocator not initialized!"); return; }
        Type type = typeof(T);
        if (_instance._services.ContainsKey(type))
        {
            Debug.LogWarning($"Service {type.Name} already registered. Overwriting.");
            _instance._services[type] = service;
        }
        else
        {
            _instance._services.Add(type, service);
        }
    }
    public static T Get<T>() where T : class
    {
        if (_instance == null) { Debug.LogError("ServiceLocator not initialized!"); return null; }
        Type type = typeof(T);
        if (_instance._services.TryGetValue(type, out object service)) return service as T;
        Debug.LogError($"Service {type.Name} not found in ServiceLocator!");
        return null;
    }
    public static bool Has<T>() where T : class => _instance != null && _instance._services.ContainsKey(typeof(T));
}

