using UnityEngine;
using Unity.Collections;
using Unity.Jobs;

public class CPUOptimization : MonoBehaviour
{
    [SerializeField] private int _agentCount = 500;
    private Vector3[] _positions;
    private Vector3[] _targets;

    private void Start()
    {
        _positions = new Vector3[_agentCount];
        _targets = new Vector3[_agentCount];
        for (int i = 0; i < _agentCount; i++)
        {
            _positions[i] = Random.insideUnitSphere * 50f;
            _targets[i] = Random.insideUnitSphere * 50f;
        }
    }

    private void Update()
    {
        // BAD: Sequential CPU-bound loop on main thread
        // for (int i = 0; i < _agentCount; i++)
        // {
        //     _positions[i] = Vector3.MoveTowards(_positions[i], _targets[i], Time.deltaTime * 5f);
        // }

        // GOOD: Parallel Job System distributes work across cores
        NativeArray<Vector3> positions = new NativeArray<Vector3>(_positions, Allocator.TempJob);
        NativeArray<Vector3> targets = new NativeArray<Vector3>(_targets, Allocator.TempJob);

        MoveAgentJob job = new MoveAgentJob
        {
            Positions = positions,
            Targets = targets,
            DeltaTime = Time.deltaTime,
            Speed = 5f
        };

        JobHandle handle = job.Schedule(_agentCount, 32);
        handle.Complete();

        positions.CopyTo(_positions);
        positions.Dispose();
        targets.Dispose();
    }

    struct MoveAgentJob : IJobParallelFor
    {
        public NativeArray<Vector3> Positions;
        [ReadOnly] public NativeArray<Vector3> Targets;
        public float DeltaTime;
        public float Speed;

        public void Execute(int index)
        {
            Positions[index] = Vector3.MoveTowards(Positions[index], Targets[index], DeltaTime * Speed);
        }
    }
}

