public class UnityPoolManager : MonoBehaviour
{
    [SerializeField] private Projectile _projectilePrefab;
    [SerializeField] private int _defaultCapacity = 50;
    [SerializeField] private int _maxPoolSize = 500;

    private ObjectPool<Projectile> _projectilePool;

    private void Awake()
    {
        _projectilePool = new ObjectPool<Projectile>(
            createFunc: CreateProjectile,
            actionOnGet: OnGetProjectile,
            actionOnRelease: OnReleaseProjectile,
            actionOnDestroy: OnDestroyProjectile,
            collectionCheck: true, // Detects double-release (debug only)
            defaultCapacity: _defaultCapacity,
            maxSize: _maxPoolSize
        );
    }

    private Projectile CreateProjectile()
    {
        Projectile proj = Instantiate(_projectilePrefab, transform);
        proj.name = $"Projectile_Pooled_{_projectilePool.CountAll}";
        return proj;
    }

    private void OnGetProjectile(Projectile proj)
    {
        proj.gameObject.SetActive(true);
        proj.OnSpawn();
    }

    private void OnReleaseProjectile(Projectile proj)
    {
        proj.OnDespawn();
        proj.gameObject.SetActive(false);
    }

    private void OnDestroyProjectile(Projectile proj)
    {
        Destroy(proj.gameObject);
    }

    public Projectile GetProjectile() => _projectilePool.Get();
    public void ReturnProjectile(Projectile proj) => _projectilePool.Release(proj);
    public void ClearProjectiles() => _projectilePool.Clear();
}

