// Custom collection with struct enumerator — zero allocation foreach
public struct FastList<T> : IEnumerable<T> where T : class
{
    private readonly T[] _items;
    private int _count;

    public FastList(int capacity)
    {
        _items = new T[capacity];
        _count = 0;
    }

    public void Add(T item)
    {
        if (_count < _items.Length)
        {
            _items[_count++] = item;
        }
    }

    public void Clear() => _count = 0;
    public int Count => _count;
    public T this[int index] => _items[index];

    // Struct enumerator — NO heap allocation
    public Enumerator GetEnumerator() => new Enumerator(_items, _count);
    IEnumerator<T> IEnumerable<T>.GetEnumerator() => new Enumerator(_items, _count);
    IEnumerator IEnumerable.GetEnumerator() => new Enumerator(_items, _count);

    public struct Enumerator : IEnumerator<T>
    {
        private readonly T[] _items;
        private readonly int _count;
        private int _index;

        public Enumerator(T[] items, int count)
        {
            _items = items;
            _count = count;
            _index = -1;
        }

        public T Current => _items[_index];
        object IEnumerator.Current => _items[_index];
        public bool MoveNext() => ++_index < _count;
        public void Reset() => _index = -1;
        public void Dispose() { } // Struct — nothing to dispose
    }
}

