public class JobSystemDemo : MonoBehaviour
{
    [SerializeField] private int _agentCount = 1000;
    [SerializeField] private float _moveSpeed = 5f;

    // NativeArray: unmanaged memory, compatible with Jobs
    private NativeArray<float3> _positions;
    private NativeArray<float3> _velocities;
    private NativeArray<float3> _targets;
    private NativeArray<float> _healths;

    private void Start()
    {
        // Allocate NativeArrays with persistent allocator (survives multiple frames)
        _positions = new NativeArray<float3>(_agentCount, Allocator.Persistent);
        _velocities = new NativeArray<float3>(_agentCount, Allocator.Persistent);
        _targets = new NativeArray<float3>(_agentCount, Allocator.Persistent);
        _healths = new NativeArray<float>(_agentCount, Allocator.Persistent);

        // Initialize random data
        for (int i = 0; i < _agentCount; i++)
        {
            _positions[i] = new float3(UnityEngine.Random.Range(-50f, 50f), 0, UnityEngine.Random.Range(-50f, 50f));
            _velocities[i] = new float3(UnityEngine.Random.Range(-1f, 1f), 0, UnityEngine.Random.Range(-1f, 1f));
            _targets[i] = new float3(UnityEngine.Random.Range(-50f, 50f), 0, UnityEngine.Random.Range(-50f, 50f));
            _healths[i] = 100f;
        }
    }

    private void Update()
    {
        // Create the job struct (copied by value to worker threads)
        MoveAgentsJob moveJob = new MoveAgentsJob
        {
            Positions = _positions,
            Velocities = _velocities,
            Targets = _targets,
            Healths = _healths,
            DeltaTime = Time.deltaTime,
            Speed = _moveSpeed
        };

        // Schedule parallel: 1 batch per 32 items (tune for your CPU)
        JobHandle moveHandle = moveJob.Schedule(_agentCount, 32);

        // Schedule another job that depends on the first
        CheckHealthJob healthJob = new CheckHealthJob
        {
            Healths = _healths,
            Positions = _positions
        };
        JobHandle healthHandle = healthJob.Schedule(_agentCount, 64, moveHandle);

        // Complete all jobs before the frame ends (synchronous wait)
        healthHandle.Complete();

        // Read results on main thread (e.g., update transforms)
        for (int i = 0; i < _agentCount; i++)
        {
            if (_healths[i] <= 0)
            {
                // Handle death on main thread (can't modify GameObjects in jobs)
                // Spawn death effect, return to pool, etc.
            }
        }
    }

    private void OnDestroy()
    {
        // CRITICAL: Dispose NativeArrays to prevent memory leaks
        _positions.Dispose();
        _velocities.Dispose();
        _targets.Dispose();
        _healths.Dispose();
    }

    // Job struct: must be blittable (no reference types, no managed arrays)
    struct MoveAgentsJob : IJobParallelFor
    {
        [NativeDisableParallelForRestriction] // Allow write access (use carefully)
        public NativeArray<float3> Positions;

        [NativeDisableParallelForRestriction]
        public NativeArray<float3> Velocities;

        [ReadOnly] public NativeArray<float3> Targets;
        [ReadOnly] public NativeArray<float> Healths;
        public float DeltaTime;
        public float Speed;

        public void Execute(int index)
        {
            // Skip dead agents
            if (Healths[index] <= 0) return;

            float3 pos = Positions[index];
            float3 target = Targets[index];
            float3 dir = math.normalize(target - pos);

            // Move towards target
            pos += dir * Speed * DeltaTime;

            // Simple boundary check
            if (math.distance(pos, target) < 0.1f)
            {
                // Pick new random target
                target = new float3(UnityEngine.Random.Range(-50f, 50f), 0, UnityEngine.Random.Range(-50f, 50f));
            }

            Positions[index] = pos;
            Velocities[index] = dir * Speed;
        }
    }

    struct CheckHealthJob : IJobParallelFor
    {
        [NativeDisableParallelForRestriction]
        public NativeArray<float> Healths;

        [ReadOnly] public NativeArray<float3> Positions;

        public void Execute(int index)
        {
            // Simulate damage from being near origin
            float distToOrigin = math.length(Positions[index]);
            if (distToOrigin < 5f)
            {
                Healths[index] -= 10f * UnityEngine.Time.deltaTime; // Can't use Time in jobs!
                // In real code, pass deltaTime as a parameter
            }
        }
    }
}

